function edit(i=null){editing=i?.id||null;$('#item-heading').textContent=i?'编辑物品':'新建物品';for(const [k,v]of Object.entries({name:i?.name||'',number:i?.assetNo||nextNumber(),category:i?.category||'',brand:i?.brand||'',model:i?.model||'',condition:i?.condition||'unknown',department:i?.department||'',custodian:i?.custodian||'',serial:i?.serial||'',purchaseDate:i?.purchaseDate||'',warrantyDate:i?.warrantyDate||'',kind:i?.kind||'asset',unit:i?.unit||'件',qty:0,low:i?.low||0,location:i?.location||'',note:i?.note||''}))$('#item-'+k).value=v;$('#item-kind').disabled=!!i;$('#item-qty').disabled=!!i;$('#item-error').textContent='';$('#item-extended').open=false;$('#item-count').value=1;$('#item-count').disabled=!!i;$('#item-condition').disabled=i?.condition==='retired';formKind();$('#item-dialog').showModal()}
